    "syntax": "import os\n\ncwd = os.getcwd()\nos.chdir(\"../\")\nos.mkdir(\"new_dir\")\nstats = os.stat(\"file.txt\")\nprint(\"Size:\", os.path.getsize(\"file.txt\"))",
